#pragma once
#include "webui_shared.h"
inline std::string get_chores_page(std::string_view version="") {
return webui::start("People & chores","chores")+R"CHOREPAGE(<style>
.layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:22px;align-items:start}.layout>div{display:grid;gap:20px}.panel-settings{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:14px;margin:0 0 22px}.panel-settings h2{margin-bottom:4px}.summary-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:20px}.summary-item{padding:18px 21px;background:var(--surface);border:1px solid var(--line);border-radius:17px}.summary-value{font-size:28px;font-weight:750;letter-spacing:-.8px}.summary-label{font-size:11px;color:var(--muted)}.person{padding:17px 0;border-top:1px solid var(--line);margin-top:18px}.person-name{font-weight:700;overflow-wrap:anywhere}.person-actions,.task-actions{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}.person-actions button,.task-actions button{min-height:40px;font-size:12px;padding:8px 12px;background:transparent}.dot{width:9px;height:9px;border-radius:50%;display:inline-block;flex-shrink:0}.task{display:flex;gap:14px;padding:21px 0;border-top:1px solid var(--line);align-items:flex-start}.task-check{display:flex;justify-content:center;align-items:flex-start;flex-shrink:0;width:44px;min-height:44px;margin:-3px -6px 0 -8px;padding:5px;cursor:pointer}.task-check input{margin:0;width:22px;height:22px;cursor:pointer}.task-title{font-size:16px;font-weight:700;overflow-wrap:anywhere;line-height:1.5}.task.done .task-title{text-decoration:line-through;color:var(--muted)}.task-meta{font-size:12px;color:var(--muted);margin-top:6px;overflow-wrap:anywhere}.task .badge{color:var(--warning);margin-left:8px}.filters{display:grid;grid-template-columns:auto minmax(0,1fr) auto minmax(0,1fr);gap:9px;align-items:center;margin-bottom:15px}.filters label{margin:0}.layout h2{margin-bottom:18px}.layout p{margin:10px 0 18px}.layout .row{flex-wrap:wrap}.layout .grid{gap:16px}.layout .grid .field{margin-bottom:0}.layout .grid{margin-bottom:18px}.page-heading .button{flex-shrink:0}.board-status{display:flex;justify-content:space-between;gap:12px;margin-bottom:14px}.person .row{flex-wrap:nowrap}.task .grow{flex:1;min-width:0}
@media(max-width:900px){.layout{grid-template-columns:260px minmax(0,1fr)}.layout .grid{grid-template-columns:minmax(0,1fr)}.filters{grid-template-columns:auto minmax(0,1fr)}}
@media(max-width:760px){.layout{grid-template-columns:minmax(0,1fr)}.layout>aside{order:1}.layout .grid{gap:16px}.summary-row{gap:9px}.summary-item{padding:14px 12px;border-radius:14px}.summary-value{font-size:24px}.summary-label{font-size:10px}.panel-settings{padding:17px}.panel-settings small{font-size:12px}.task-title{font-size:15px}.layout>div{gap:16px}.person-actions button,.task-actions button{min-height:44px}.board-status{flex-wrap:wrap}}
</style>
<div class="page-heading"><div><div class="eyebrow">A little teamwork</div><h1>Make room for the everyday.</h1><p>Your people, their chores, and one less thing to keep in your head.</p></div><a class="button quiet" href="/#remote">Back to frame</a></div>
<div id="error" class="notice" role="alert" hidden></div><div class="board-status"><div id="status" class="status" aria-live="polite">Loading your household…</div></div>
<div class="summary-row" aria-label="Household summary"><div class="summary-item"><div id="summary-people" class="summary-value">—</div><div class="summary-label">People at home</div></div><div class="summary-item"><div id="summary-due" class="summary-value">—</div><div class="summary-label">Chores to go</div></div><div class="summary-item"><div id="summary-done" class="summary-value">—</div><div class="summary-label">Done today</div></div></div>
<section class="card panel-settings" aria-label="Display settings"><div><h2>Chores on your frame</h2><small>Equal side panels keep photos and videos centered, above the news ticker.</small></div><div class="stack" style="gap:6px"><label class="check-label"><input id="panel" type="checkbox" disabled>Show left panel</label><label class="check-label"><input id="panel-clock" type="checkbox" disabled>Show 12-hour clock</label></div></section>
<div class="layout"><aside class="stack">
<section class="card"><h2 id="person-heading">Your people</h2><form id="person-form"><input id="person-id" type="hidden"><div class="field"><label for="person-name">Name</label><input id="person-name" maxlength="80" autocomplete="off" placeholder="e.g. Alex" required></div><div class="row"><label for="person-color">Color</label><input id="person-color" type="color" value="#38bdf8"><button id="person-submit" class="primary" type="submit">Add person</button></div><button id="person-cancel" type="button" hidden style="margin-top:12px">Cancel edit</button></form><div id="people"></div></section>
<section class="card"><h2>How it works</h2><p class="hint">Daily chores start fresh each local day. A chore for one date stays overdue until it's done. All-day chores have no deadline; timed chores show their due time.</p><div id="zone" class="hint"></div></section>
</aside><div>
<section class="card"><h2 id="chore-heading">Add a chore</h2><form id="chore-form"><input id="chore-id" type="hidden"><div class="grid"><div class="field"><label for="chore-title">What needs doing?</label><input id="chore-title" maxlength="160" placeholder="e.g. Feed the cat" required></div><div class="field"><label for="chore-person">Who's responsible?</label><select id="chore-person" required><option value="">Add a person first</option></select></div></div><div class="grid"><div class="field"><label for="chore-repeat">When?</label><select id="chore-repeat"><option value="daily">Every day</option><option value="once">On a specific date</option></select></div><div id="date-field" class="field" hidden><label for="chore-date">Date</label><input id="chore-date" type="date"></div></div><div class="row field"><label class="check-label"><input id="all-day" type="checkbox" checked>All day</label><div id="time-field" class="grow" hidden><label for="chore-time">Due at</label><input id="chore-time" type="time"></div></div><div class="row"><button id="chore-submit" class="primary" type="submit" disabled>Add chore</button><button id="chore-cancel" type="button" hidden>Cancel edit</button></div><p id="assign-hint" class="hint">Add someone to your household to get started.</p></form></section>
<section class="card"><div class="row" style="justify-content:space-between"><h2>The chore board</h2><small id="counts"></small></div><div class="field"><label class="sr-only" for="chore-search">Find a chore</label><input id="chore-search" type="search" placeholder="Find a chore or person…"></div><div class="filters"><label for="view" class="hint">View</label><select id="view"><option value="today">Today &amp; overdue</option><option value="upcoming">Upcoming</option><option value="all">All chores</option></select><label for="person-filter" class="hint">Person</label><select id="person-filter"><option value="">Everyone</option></select></div><div id="tasks"></div></section>
</div></div>
<script>
'use strict';
const $=FrameUI.$;
let state={people:[],chores:[],today:''}, readSequence=0, choreRevision='';
function notice(message){$('error').textContent=message||'';$('error').hidden=!message;}
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
async function api(path,fields){return FrameUI.request(path,fields===undefined?{}:{fields});}
function button(label,action,danger=false){const b=el('button',label,danger?'danger':'');b.type='button';b.addEventListener('click',action);return b;}
function scheduleFields(){$('date-field').hidden=$('chore-repeat').value!=='once';$('chore-date').required=!$('date-field').hidden;$('time-field').hidden=$('all-day').checked;$('chore-time').required=!$('all-day').checked;}
function resetPerson(){$('person-form').reset();$('person-id').value='';$('person-heading').textContent='Your people';$('person-submit').textContent='Add person';$('person-cancel').hidden=true;}
function resetChore(){$('chore-form').reset();$('chore-id').value='';choreRevision='';$('chore-date').value=state.today;$('chore-heading').textContent='Add a chore';$('chore-submit').textContent='Add chore';$('chore-cancel').hidden=true;scheduleFields();}
function editPerson(p){$('person-id').value=p.id;$('person-name').value=p.name;$('person-color').value=p.color;$('person-heading').textContent='Edit person';$('person-submit').textContent='Save person';$('person-cancel').hidden=false;$('person-name').focus();}
function editChore(c){$('chore-id').value=c.id;choreRevision=c.revision??'';$('chore-title').value=c.title;$('chore-person').value=c.person_id;$('chore-repeat').value=c.repeat;$('chore-date').value=c.date||state.today;$('all-day').checked=c.all_day;$('chore-time').value=c.time;$('chore-heading').textContent='Edit chore';$('chore-submit').textContent='Save chore';$('chore-cancel').hidden=false;scheduleFields();$('chore-title').focus();}
async function change(path,fields){try{notice('');await api(path,fields);await load();$('status').textContent='Saved to your frame.';return true;}catch(e){await load();notice(e.message);return false;}}
function render(){
 const people=$('people');people.replaceChildren();const selected=$('chore-person').value,filter=$('person-filter').value;
 $('chore-person').replaceChildren(el('option',state.people.length?'Choose a person':'Add a person first'));$('chore-person').firstChild.value='';$('person-filter').replaceChildren(el('option','Everyone'));$('person-filter').firstChild.value='';
 for(const p of state.people){const option=el('option',p.name);option.value=p.id;$('chore-person').append(option);const f=option.cloneNode(true);$('person-filter').append(f);const row=el('div',undefined,'person'),name=el('div',undefined,'row'),dot=el('span',undefined,'dot');dot.style.backgroundColor=p.color;name.append(dot,el('span',p.name,'person-name'));row.append(name);const assigned=state.chores.filter(c=>c.person_id===p.id).length;row.append(el('small',assigned+' assigned chore'+(assigned===1?'':'s')));const actions=el('div',undefined,'person-actions');actions.append(button('Edit',()=>editPerson(p)));const remove=button('Remove',async()=>{if(confirm('Remove '+p.name+' from your household?')){if(await change('/api/chores/people/delete',{id:p.id}))resetPerson();}},true);remove.disabled=assigned>0;remove.title=assigned?'Reassign or delete their chores first':'Remove person';actions.append(remove);row.append(actions);people.append(row);}
 if(selected)$('chore-person').value=selected;else if(state.people.length===1)$('chore-person').value=state.people[0].id;if(filter)$('person-filter').value=filter;
 $('chore-submit').disabled=!state.people.length;$('assign-hint').hidden=!!state.people.length;
 $('zone').textContent='Household time: '+state.timezone+' · '+state.today;
 renderTasks();
}
function renderTasks(){const person=$('person-filter').value,view=$('view').value,search=$('chore-search').value.trim().toLowerCase();const rows=state.chores.filter(c=>(!search||(c.title+' '+(state.people.find(p=>p.id===c.person_id)?.name||'')).toLowerCase().includes(search))&&(!person||String(c.person_id)===person)&&(view==='all'||(view==='today'?c.due:(!c.due&&c.repeat==='once'&&c.date>state.today)))).sort((a,b)=>Number(a.completed)-Number(b.completed)||(a.date||state.today).localeCompare(b.date||state.today)||a.time.localeCompare(b.time)||a.id-b.id);const tasks=$('tasks');tasks.replaceChildren();const due=state.chores.filter(c=>c.due);$('summary-people').textContent=state.people.length;$('summary-due').textContent=due.filter(c=>!c.completed).length;$('summary-done').textContent=due.filter(c=>c.completed).length;$('counts').textContent=due.filter(c=>c.completed).length+' / '+due.length+' done today';
 if(!rows.length)tasks.append(el('div',state.chores.length?'Nothing in this view. Enjoy the breathing room.':'Your first chore starts here. Add one above.','empty'));
 for(const c of rows){const p=state.people.find(p=>p.id===c.person_id),row=el('div',undefined,'task'+(c.completed?' done':''));const check=el('input');check.type='checkbox';check.checked=c.completed;check.setAttribute('aria-label',(c.completed?'Mark incomplete: ':'Complete: ')+c.title);check.addEventListener('change',async()=>{check.disabled=true;const ok=await change('/api/chores/tasks/complete',{id:c.id,date:c.repeat==='daily'?state.today:c.date,completed:check.checked?'1':'0'});if(!ok){check.checked=c.completed;check.disabled=false;}});const content=el('div',undefined,'grow');content.style.minWidth='0';const title=el('div',c.title,'task-title');if(!c.completed&&c.repeat==='once'&&c.date<state.today)title.append(el('span','Overdue','badge'));content.append(title);const meta=el('div',undefined,'task-meta'),dot=el('span',undefined,'dot');dot.style.backgroundColor=p?p.color:'#38bdf8';meta.append(dot,document.createTextNode(' '+(p?p.name:'Unknown person')+' · '+(c.repeat==='daily'?'Every day':c.date)+' · '+(c.all_day?'All day':c.time)));content.append(meta);const actions=el('div',undefined,'task-actions');actions.append(button('Edit',()=>editChore(c)),button('Delete',async()=>{if(confirm('Delete “'+c.title+'”?')){if(await change('/api/chores/tasks/delete',{id:c.id}))if($('chore-id').value===String(c.id))resetChore();}},true));content.append(actions);const checkLabel=el('label',undefined,'task-check');checkLabel.append(check);row.append(checkLabel,content);tasks.append(row);}
}
async function load(){const sequence=++readSequence;try{const data=await api('/api/chores');if(sequence!==readSequence)return;state=data;render();FrameUI.connection(true);if(!$('chore-date').value)$('chore-date').value=state.today;$('status').textContent='Chores follow your frame’s local time.';}catch(e){notice(e.message);if(e.status!==401)FrameUI.connection(false);$('status').textContent='';}}
$('chore-repeat').addEventListener('change',scheduleFields);$('all-day').addEventListener('change',scheduleFields);$('person-cancel').addEventListener('click',resetPerson);$('chore-cancel').addEventListener('click',resetChore);$('chore-search').addEventListener('input',renderTasks);$('view').addEventListener('change',renderTasks);$('person-filter').addEventListener('change',renderTasks);
$('person-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('person-submit');b.disabled=true;if(await change('/api/chores/people/save',{id:$('person-id').value,name:$('person-name').value.trim(),color:$('person-color').value}))resetPerson();b.disabled=false;});
$('chore-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('chore-submit');b.disabled=true;if(await change('/api/chores/tasks/save',{id:$('chore-id').value,revision:choreRevision,person_id:$('chore-person').value,title:$('chore-title').value.trim(),repeat:$('chore-repeat').value,date:$('chore-date').value,all_day:$('all-day').checked?'1':'0',time:$('chore-time').value}))resetChore();b.disabled=!state.people.length;});
FrameUI.onUnlock(async()=>{notice('');await load();await panelSettings();});
async function panelSettings(){try{const settings=await api('/api/settings');$('panel').checked=!!settings.left_panel_enabled&&!!settings.infopanels_enabled;$('panel').disabled=false;$('panel-clock').checked=!!settings.left_panel_clock_enabled;$('panel-clock').disabled=false;}catch(e){notice(e.message);}}
$('panel').addEventListener('change',async()=>{const control=$('panel');control.disabled=true;try{notice('');await FrameUI.request('/api/settings/update?left_panel_enabled='+(control.checked?'1&infopanels_enabled=1':'0'));$('status').textContent=control.checked?'Left panel enabled on your frame.':'Left panel hidden. Your chores are saved.';FrameUI.toast('Frame panel updated.');}catch(e){control.checked=!control.checked;notice(e.message);}finally{control.disabled=false;}});
$('panel-clock').addEventListener('change',async()=>{const control=$('panel-clock');control.disabled=true;try{notice('');await FrameUI.request('/api/settings/update?left_panel_clock_enabled='+(control.checked?'1':'0'));FrameUI.toast(control.checked?'Chores clock enabled.':'Chores clock hidden.');}catch(e){control.checked=!control.checked;notice(e.message);}finally{control.disabled=false;}});
scheduleFields();load();panelSettings();setInterval(()=>{if(!document.hidden)load();},30000);

</script>)CHOREPAGE"+webui::end(version);
}
